import {adventureHost,configureHostedWorld} from '../shared/adventure-host.js';
import {bindControls,createAudio,writeSaved,registerAdventure,backToArcade} from '../shared/runtime.js';
import {VOCAB,HINTS,byId,choicesFor,shuffle,freshProgress,readProgress,recordAnswer} from './vocabulary.js';
import {LEVELS,makeWorld,newPlayer,updatePhysics} from './world.js';
import {titleArt,drawWorld,crystal} from './art.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),overlay=$('overlay');
let progress;try{progress=readProgress(localStorage);}catch{progress=freshProgress();}
let controls=null,frameId=0,disposed=false;
let mode='menu',world=null,player=null,camera=0,clock=0,effects=[],hearts=3,checkpoint=100,rockClock=0;
let input={left:false,right:false,jump:false},activePointers=new Map(),keys=new Set(),toastUntil=0,audio=null;
let question=null,stationQueue=[],currentStation=null,practiceQueue=[],practiceDone=0,practiceTotal=0;
let cards=[],cardIndex=0,cardFlipped=false,filterCards=false,bossPulse=0,nextHudAt=0;
function save(){try{if(!writeSaved(localStorage,'volcano-quest-v1',progress))throw Error();$('save-warning').hidden=true;}catch{$('save-warning').hidden=false;}}
function saveRun(){if(!world||!progress.run)return;Object.assign(progress.run,{level:world.index,checkpoint,powerTime:player.powerTime||0,powerKind:player.powerKind||'jump',done:world.stations.filter(s=>s.done).map(s=>s.id),collected:world.crystals.filter(c=>c.taken).map(c=>c.id)});save();}
const audioEngine=createAudio({jump:[280,430],crystal:[700,1050],correct:[523,659,784],wrong:[230,200],open:[380,570],win:[523,659,784,1047],hurt:[150,95]});
function sound(type){audioEngine.play(type,progress.sound);}
function resetInput(){controls?.clear();input={left:false,right:false,jump:false};}
function setMode(next){try{window.speechSynthesis?.cancel();}catch{}mode=next;resetInput();$('controls').hidden=next!=='play';$('hud').hidden=!['play','pause','question'].includes(next);if(next!=='play')$('action').hidden=true;}
function show(html){overlay.innerHTML=html;}
function on(id,fn){$(id)?.addEventListener('click',fn);}
function questionSpeechControl(){return '<div class="question-speech"><button class="secondary" id="read-question">🔊 SPEAK ALOUD</button><small id="speech-status" role="status"></small></div>';}
function speakQuestion(){
 const status=$('speech-status');
 if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){status.textContent='Read-aloud is unavailable in this browser. A grown-up can read with you.';return;}
 const panel=document.querySelector('.question');
 const prompt=[panel.querySelector('h2').textContent,...[...panel.querySelectorAll(':scope > p:not(.eyebrow)')].map(p=>p.textContent)].join('. ');
 const choices=[...panel.querySelectorAll('[data-answer]')].map((b,i)=>`Choice ${i+1}. ${b.textContent}`);
 try{window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance([prompt,...choices].join('. '));utterance.lang='en-US';utterance.rate=.85;utterance.onerror=e=>{if(!['canceled','interrupted'].includes(e.error)&&status.isConnected)status.textContent='Read-aloud could not start. Please tap Speak Aloud to try again.';};window.speechSynthesis.speak(utterance);status.textContent='Reading the question and choices.';}catch{status.textContent='Read-aloud could not start. Please tap Speak Aloud to try again.';}
}
function toast(text,seconds=3){$('toast').textContent=text;toastUntil=clock+seconds;$('toast').classList.add('visible');}
function burst(x,y,color='#ffe599',count=18){for(let i=0;i<count;i++)effects.push({x,y,vx:(Math.random()-.5)*240,vy:-80-Math.random()*190,life:.5+Math.random()*.5,max:1,size:3+Math.random()*4,color});}
function soundLabel(){const text=progress.sound?'♪ ON':'♪ OFF';$('sound').textContent=text;$('sound').setAttribute('aria-label',progress.sound?'Turn sound off':'Turn sound on');if($('menu-sound'))$('menu-sound').textContent=`Sound ${progress.sound?'on':'off'}`;}
function toggleSound(){progress.sound=!progress.sound;soundLabel();save();if(progress.sound)sound('correct');}
on('sound',toggleSound);
function mainMenu(){setMode('menu');show(`<section class="title-screen"><p class="eyebrow">EMBERIA’S ADVENTURE • A little explorer. A big discovery.</p><h1>VOLCANO<span>QUEST</span></h1><p class="subtitle">Escape the Eruption!</p><p class="story">An island to save. A world beneath your feet.<br>Let your science powers lead the way.</p><div class="menu-buttons"><button class="primary" id="play">${progress.run?'CONTINUE ADVENTURE':'PLAY ADVENTURE'} &nbsp;➜</button><button class="secondary" id="study">PRACTICE FOR TEST</button><button class="secondary" id="practice">PRACTICE MY MISTAKES</button></div>${progress.run?'<button class="new-run text-btn" id="new-adventure">PLAY ADVENTURE AGAIN</button>':''}<div class="menu-footer"><button class="text-btn" id="menu-sound">Sound off</button><button class="text-btn" id="help">How to play</button><button class="text-btn" id="parent-progress">Parent Progress</button><button class="text-btn" id="back-arcade">Back to Arcade</button>${progress.lastResult?'<button class="text-btn" id="last-result">Last trophy</button>':''}</div><span class="island-label">EXPLORE • DISCOVER • SAVE THE ISLAND</span></section>`);on('play',()=>progress.run?loadLevel(progress.run.level):intro());on('new-adventure',intro);on('study',()=>openStudy(false));on('practice',startPractice);on('menu-sound',toggleSound);on('help',help);on('parent-progress',parentDashboard);on('back-arcade',backToArcade);on('last-result',()=>results(progress.lastResult));soundLabel();}
function parentDashboard(){setMode('parent');show(`<section class="panel ari-parent"><p class="eyebrow">EMBERIA’S PARENT LEARNING JOURNAL</p><h2>Earth Science progress</h2><p>First try counts each fresh question. A correct retry does not count as first-try mastery. A later first-try answer clears the practice flag.</p><p>${progress.run?'Adventure saved at chapter '+(progress.run.level+1)+'. Crystals: '+progress.run.crystals:progress.lastResult?'Last adventure: '+progress.lastResult.crystals+' crystals, '+progress.lastResult.first+'/13 first try.':'No adventure completed yet.'}</p><div class="ari-table-scroll"><table><thead><tr><th>Word</th><th>Practiced</th><th>First try</th><th>Mistakes</th><th>Review</th><th>Latest result</th></tr></thead><tbody>${VOCAB.map(v=>{const t=progress.stats[v.id];return `<tr><td><strong>${v.term}</strong><br>${v.definition}</td><td>${t.encounters?'Yes':'No'}</td><td>${t.firstCorrect}/${t.encounters}${t.encounters?' • '+Math.round(t.firstCorrect/t.encounters*100)+'%':''}</td><td>${t.incorrect}</td><td>${t.needsPractice?'Practice':t.firstCorrect?'✓ Latest first try':'Not assessed'}</td><td>${t.latest||'Not practiced'}</td></tr>`;}).join('')}</tbody></table></div><div class="row"><button class="primary" id="parent-back">ADVENTURE MENU</button><button class="secondary" id="reset">RESET EMBERIA’S PROGRESS</button></div></section>`);on('parent-back',mainMenu);on('reset',resetDialog);}
function intro(){setMode('intro');show(`<section class="panel"><p class="eyebrow">YOUR ADVENTURE STARTS HERE</p><h2>The island needs you!</h2><p>The magical volcano has the hiccups! Find ancient crystals, explore Earth’s layers, and help the friendly Volcano Guardian calm the island.</p><p>Hold ◀ or ▶ to run. Tap ↑ to jump.<br>Press <strong>✦ EXPLORE</strong> near a glowing discovery.</p><p>Take your time. Every discovery is a new science power.</p><button class="primary" id="begin">LET’S EXPLORE! ➜</button></section>`);on('begin',()=>{progress.run={level:0,checkpoint:100,done:[],collected:[],crystals:0,score:0,answers:{},bossDone:0,bossTerms:[],started:Date.now()};save();loadLevel(0);});}
function loadLevel(index){world=configureHostedWorld(makeWorld(index));const run=progress.run;checkpoint=run?.checkpoint||100;hearts=3;player=newPlayer(checkpoint,470);player.powerTime=run.powerTime||0;player.powerKind=run.powerKind||'jump';player.checkpoint=checkpoint;world.stations.forEach(s=>s.done=run.done.includes(s.id));world.crystals.forEach(c=>c.taken=run.collected.includes(c.id));camera=Math.max(0,Math.min(5000,checkpoint-350));rockClock=0;effects=[];show('');setMode('play');updateHud();toast(LEVELS[index].subtitle,5);saveRun();const pending=adventureHost()?.pendingStation;if(pending){currentStation=world.stations.find(s=>s.id===pending);if(currentStation)nextStationQuestion();}}
function updateHud(){if(!world)return;$('crystals').textContent=`◆ ${progress.run?.crystals||0}`;$('power').hidden=!(player.powerTime>0);$('power').textContent=`${player.powerKind==='speed'?'⚡ DOUBLE SPEED':'↑↑ DOUBLE JUMP'} · ${Math.ceil(player.powerTime||0)}s`;$('hearts').textContent='♥ '.repeat(hearts)+'♡ '.repeat(3-hearts);$('level-number').textContent=`CHAPTER ${world.index+1} / 3`;$('level-name').textContent=adventureHost()?.stageName||LEVELS[world.index].short;$('progress-fill').style.width=`${Math.min(100,player.x/5950*100)}%`;soundLabel();}
function help(){setMode('help');show(`<section class="panel"><p class="eyebrow">EXPLORER’S FIELD GUIDE</p><h2>Follow your curiosity!</h2><p><strong>◀ ▶ Move &nbsp; ↑ Jump &nbsp; ✦ Explore</strong></p><p>Use both thumbs: hold a direction while tapping jump. Follow the crystals and find glowing discoveries to unlock each path.</p><p>Flags save your place. If you fall, you return to your last flag. There’s no game over and no question timer.</p><p>On a computer: arrow keys or A / D, Space to jump, E to explore, Esc to pause. Sound is optional.</p><button class="primary" id="back">GOT IT!</button></section>`);on('back',mainMenu);}
function resetDialog(){setMode('reset');show(`<section class="panel"><h2>Start with a fresh explorer journal?</h2><p>This clears this browser’s adventure, crystals, and vocabulary practice.</p><div class="row"><button class="secondary" id="cancel-reset">KEEP MY PROGRESS</button><button class="primary" id="confirm-reset">RESET PROGRESS</button></div></section>`);on('cancel-reset',mainMenu);on('confirm-reset',()=>{progress=freshProgress();world=null;player=null;save();mainMenu();});}
function pause(){if(mode!=='play')return;saveRun();setMode('pause');show(`<section class="panel"><p class="eyebrow">TAKE A LITTLE BREATHER</p><h2>Adventure paused</h2><p>Your latest checkpoint is saved.<br>The island will wait for you.</p><div class="row"><button class="primary" id="resume">KEEP EXPLORING</button><button class="secondary" id="quit">MAIN MENU</button></div></section>`);on('resume',()=>{show('');setMode('play');});on('quit',()=>adventureHost()?adventureHost().menu():mainMenu());}
on('pause',pause);
function damage(){if(player.hurt>0)return;hearts--;sound('hurt');burst(player.x,player.y,'#ffb5bc',12);player.x=checkpoint;player.y=460;player.vy=0;player.vx=0;player.hurt=1.8;camera=Math.max(0,checkpoint-350);if(hearts<=0){hearts=3;toast('A fresh start at your flag. You’ve got this!');}else toast('Back to your flag — your crystals are safe!');resetInput();updateHud();}
function nearestStation(){return world?.stations.find(s=>!s.done&&Math.abs(player.x-s.x)<128&&player.y>390);}
function interact(){if(mode!=='play')return;const s=nearestStation();if(!s)return;sound('open');currentStation=s;if(s.type==='boss'){
 const run=progress.run;if(!run.bossTerms.length){const hard=VOCAB.filter(v=>progress.stats[v.id].needsPractice).map(v=>v.id);run.bossTerms=[...new Set([...shuffle(hard).slice(0,2),...shuffle(VOCAB.map(v=>v.id))])].slice(0,3);save();}stationQueue=[run.bossTerms[run.bossDone]];
 }else stationQueue=[...s.terms];nextStationQuestion();}
function artFor(type,id){if(type==='layers')return `<div class="science-art"><div class="rock-stack"><span>Outside → ?</span><span>Middle → ?</span><span>Center → ?</span></div></div>`;if(type==='dating')return `<div class="science-art"><div class="rock-stack"><span>TOP</span><span>MIDDLE</span><span>BOTTOM</span></div></div>`;if(type==='volcano')return `<div class="science-art"><div class="volcano-cut"><span class="surface">A • surface</span><span class="inside">B • inside Earth</span></div></div>`;if(type==='hammer')return `<div class="science-art" aria-label="Weathering breaks rocks; erosion moves the pieces"><svg viewBox="0 0 400 90" width="360" height="85"><path d="M35 75 20 30 65 15 95 45 85 75Z" fill="#aeb4d5"/><path d="M60 20 50 40 70 50 55 74" fill="none" stroke="#434767" stroke-width="5"/><text x="110" y="53" fill="#ffdb86" font-size="30">→</text><path d="M160 70 147 47 170 40 180 65Z M190 72 187 42 212 55Z M225 70 232 47 250 71Z" fill="#aeb4d5"/><path d="M275 57h75m-15-10 15 10-15 10" stroke="#9fe1d7" stroke-width="5" fill="none"/><text x="270" y="88" fill="#d4ebe1" font-size="15">wind moves pieces</text></svg></div>`;if(type==='boss')return `<div class="science-art"><span style="font-size:40px">◆</span><div><strong>STABILIZER ${progress.run.bossDone} / 3</strong><br><small>${3-progress.run.bossDone} science crystals to go</small></div></div>`;return `<div class="science-art" style="font-size:52px">${type==='fossil'?'🐚':type==='chest'?'✦':type==='plates'?'⇆':'◆'}</div>`;}
function nextStationQuestion(){const host=adventureHost();if(host){setMode('question');show('');stationQueue=[];host.challenge(currentStation.id,2,kind=>{if(kind){player.powerKind=kind;player.powerTime=15;player.airJumpUsed=false;}if(currentStation.type==='boss')progress.run.bossDone=2;completeStation();});return;}const id=stationQueue.shift();if(!id){completeStation();return;}ask(id,{type:currentStation.type,title:currentStation.name},()=>nextStationQuestion());}
function ask(id,context,done){
 setMode('question');question={id,attempt:0,done,context};let prompt=byId(id).definition;
 if(context.type==='dating')prompt='In these undisturbed rock layers, which is oldest? Which skill compares the ages of rock layers?';
 if(context.type==='volcano')prompt=id==='magma'?'Look at B, inside Earth. What do we call melted rock inside Earth?':'Look at A, on the surface. What do we call melted rock that flows out of Earth’s surface?';
 if(context.type==='layers'){layerQuestion(id,context,done);return;}
 const options=context.type==='dating'?shuffle([{id:'dating',term:'BOTTOM • RELATIVE DATING'},{id:'top-dating',term:'TOP • RELATIVE DATING'},{id:'weathering',term:'MIDDLE • WEATHERING'},{id:'erosion',term:'TOP • EROSION'}]):choicesFor(id);
 show(`<section class="panel question"><p class="eyebrow">${context.title}</p>${artFor(context.type,id)}<h2>${prompt}</h2>${questionSpeechControl()}<div class="answers">${options.map(v=>`<button class="answer" data-answer="${v.id}">${v.term}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite">Choose a word to power your discovery.</div><div class="row"><button class="primary" id="question-next" hidden>CONTINUE ➜</button></div></section>`);
 document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(b.dataset.answer,b)));on('read-question',speakQuestion);on('question-next',()=>question.done());
}
function layerQuestion(id,context){const placed=['crust','mantle','core'].slice(0,3-stationQueue.length-1);const label=id==='crust'?'outside':id==='mantle'?'middle':'center';show(`<section class="panel question"><p class="eyebrow">${context.title} • OUTSIDE → CENTER</p><h2>Build Earth, one layer at a time</h2><p>Tap the <strong>${label}</strong> layer.</p>${questionSpeechControl()}<div class="order-slots">${[0,1,2].map((_,i)=>`<span>${placed[i]?byId(placed[i]).term:i===placed.length?'?':'·'}</span>`).join('')}</div><div class="answers">${shuffle(['crust','mantle','core']).map(a=>`<button class="answer" data-answer="${a}">${byId(a).term}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite">Outside first, center last.</div><div class="row"><button class="primary" id="question-next" hidden>NEXT LAYER ➜</button></div></section>`);document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(b.dataset.answer,b)));on('read-question',speakQuestion);on('question-next',()=>question.done());}
function answer(chosen,button){if(question.solved)return;const correct=chosen===question.id;recordAnswer(progress.stats,question.id,correct,question.attempt);
 if(progress.run&&currentStation){const a=progress.run.answers[question.id];if(a===undefined)progress.run.answers[question.id]=correct;}
 question.attempt++;save();if(!correct){button.classList.add('wrong');button.disabled=true;sound('wrong');$('feedback').textContent=`Try again! ${HINTS[question.id]}`;return;}
 question.solved=true;button.classList.add('correct');document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);sound('correct');$('feedback').textContent=`${question.attempt===1?'You discovered it!':'You kept trying — great exploring!'} ${byId(question.id).definition}`;$('question-next').hidden=false;
 if(progress.run&&currentStation){progress.run.crystals+=3;if(stationQueue.length===0&&(currentStation.type!=='boss'||progress.run.bossDone===2))offerPowerChoice();progress.run.score+=question.attempt===1?100:40;saveRun();updateHud();}
}
function offerPowerChoice(){
 document.querySelectorAll('[data-answer]').forEach(b=>b.hidden=true);
 $('question-next').hidden=true;
 $('feedback').insertAdjacentHTML('afterend',`<div class="power-choices"><p>Choose your power! <strong>15 seconds</strong> of exploring.</p><div class="answers"><button class="answer" data-power="speed">⚡ DOUBLE SPEED<small>Run twice as fast</small></button><button class="answer" data-power="jump">↑↑ DOUBLE JUMP<small>Jump again in the air</small></button></div><p id="power-note" aria-live="polite"></p></div>`);
 document.querySelectorAll('[data-power]').forEach(button=>button.addEventListener('click',()=>{
  player.powerKind=button.dataset.power;player.powerTime=15;player.airJumpUsed=false;
  document.querySelectorAll('[data-power]').forEach(b=>{b.classList.toggle('correct',b===button);b.setAttribute('aria-pressed',String(b===button));});
  $('power-note').textContent=player.powerKind==='speed'?'Double speed ready! Hold an arrow to zoom.':'Double jump ready! Tap Jump again in the air.';
  $('question-next').hidden=false;saveRun();updateHud();sound('open');
 }));
}
function completeStation(){const s=currentStation;if(s.type==='boss'){
 progress.run.bossDone++;bossPulse=2;burst(s.x,330,'#a6f7d4',45);if(progress.run.bossDone<3){saveRun();show('');setMode('play');currentStation=null;toast(`Stabilizer ${progress.run.bossDone}/3! Catch the next glowing science crystal.`,5);return;}
 }
 s.done=true;s.activated=world.time;checkpoint=s.x+70;player.checkpoint=checkpoint;player.x=Math.max(player.x,s.x-30);burst(s.x+170,400,LEVELS[world.index].color,50);saveRun();sound('correct');show('');setMode('play');currentStation=null;
 const messages={fossil:'Discovery saved! Tiny sediment pieces can surround a fossil.',chest:'Treasure unlocked! Heat and pressure change rocks.',hammer:'Crystal hammer activated! Weathering breaks; erosion moves.',layers:'Elevator powered! Crust → Mantle → Core.',plates:'The two crust plates shift together — a bridge appears!',dating:'In undisturbed layers: older below, younger above.',volcano:'Magma inside. Lava outside. Cooling bridge activated!',boss:'The volcano is calm! Follow the crystals to the glowing exit.'};toast(messages[s.type],6);
}
function levelEnd(){if(adventureHost()){setMode('level');saveRun();adventureHost().complete();return;}saveRun();setMode('level');sound('win');if(world.index===2){finish();return;}show(`<section class="panel"><p class="eyebrow">CHAPTER ${world.index+1} COMPLETE</p><div class="trophy">✦</div><h2>${world.index===0?'The ancient passage is open!':'The path to the volcano is ready!'}</h2><p>${world.index===0?'Your crystal hammer cleared the rocks. Now travel through Earth’s layers!':'You explored Earth’s layers. The Volcano Guardian is waiting for your help!'}</p><p>◆ ${progress.run.crystals} crystals collected</p><button class="primary" id="next-level">NEXT CHAPTER ➜</button></section>`);on('next-level',()=>{Object.assign(progress.run,{level:world.index+1,checkpoint:100,done:[],collected:[]});save();loadLevel(progress.run.level);});}
function finish(){const run=progress.run;const first=Object.values(run.answers).filter(Boolean).length;const mastered=VOCAB.filter(v=>progress.stats[v.id].firstCorrect>0&&!progress.stats[v.id].needsPractice).map(v=>v.id);const needs=VOCAB.filter(v=>progress.stats[v.id].needsPractice).map(v=>v.id);const result={crystals:run.crystals,score:run.score,first,mastered,needs,stars:first>=12?3:first>=8?2:1,date:new Date().toLocaleDateString()};progress.lastResult=result;progress.run=null;save();results(result);}
function results(r){setMode('result');show(`<section class="panel"><p class="eyebrow">ADVENTURE COMPLETED!</p><div class="trophy">🏆</div><h2>You saved the island!</h2><div class="stars">${'★'.repeat(r.stars)}${'☆'.repeat(3-r.stars)}</div><div class="stats-grid"><div class="stat"><strong>${r.crystals}</strong>CRYSTALS</div><div class="stat"><strong>${r.score}</strong>SCORE</div><div class="stat"><strong>${r.first}/13</strong>FIRST TRY</div><div class="stat"><strong>${r.mastered.length}</strong>TERMS MASTERED</div></div><div class="terms"><strong>Mastered:</strong> ${r.mastered.map(id=>byId(id).term).join(', ')||'Your discoveries are a great start.'}<br><strong>Keep practicing:</strong> ${r.needs.map(id=>byId(id).term).join(', ')||'No words currently marked for practice. Great reviewing!'}</div><div class="row"><button class="primary" id="again">PLAY AGAIN</button><button class="secondary" id="review">PRACTICE MY MISTAKES</button><button class="secondary" id="cards">PRACTICE FOR TEST</button></div><button class="text-btn" id="home">MAIN MENU</button></section>`);on('again',intro);on('review',startPractice);on('cards',()=>openStudy(false));on('home',mainMenu);}
function startPractice(){currentStation=null;practiceQueue=shuffle(VOCAB.filter(v=>progress.stats[v.id].needsPractice).map(v=>v.id));practiceTotal=practiceQueue.length;practiceDone=0;if(!practiceTotal){setMode('practice');show(`<section class="panel"><p class="eyebrow">YOUR EXPLORER JOURNAL</p><h2>No mistakes waiting!</h2><p>Play an adventure to find your tricky words, or explore all 13 flashcards.</p><div class="row"><button class="primary" id="all-cards">STUDY ALL CARDS</button><button class="secondary" id="home">MAIN MENU</button></div></section>`);on('all-cards',()=>openStudy(false));on('home',mainMenu);return;}nextPractice();}
function nextPractice(){if(!practiceQueue.length){setMode('practice');const left=VOCAB.filter(v=>progress.stats[v.id].needsPractice).length;show(`<section class="panel"><div class="trophy">✦</div><h2>Your science powers are growing!</h2><p>${practiceDone} words practiced. ${left?`${left} still need a little practice.`:'You got every practice word on your first try!'}</p><p>Getting a word after a hint helps you learn. A fresh first-try answer clears its practice flag.</p><div class="row"><button class="primary" id="review-more">PRACTICE AGAIN</button><button class="secondary" id="home">MAIN MENU</button></div></section>`);on('review-more',startPractice);on('home',mainMenu);return;}const id=practiceQueue.shift();ask(id,{type:'practice',title:`PRACTICE ${practiceDone+1} / ${practiceTotal}`},()=>{practiceDone++;nextPractice();});$('hud').hidden=true;}
function openStudy(filter){setMode('study');currentStation=null;filterCards=filter;cards=VOCAB.filter(v=>!filterCards||progress.stats[v.id].needsPractice);cardIndex=0;cardFlipped=false;renderCard();}
function renderCard(){if(!cards.length){show(`<section class="panel"><h2>No practice cards yet!</h2><p>Your explorer journal will collect tricky words as you play.</p><div class="row"><button class="primary" id="show-all">SHOW ALL 13</button><button class="secondary" id="home">MAIN MENU</button></div></section>`);on('show-all',()=>openStudy(false));on('home',mainMenu);return;}
 const v=cards[cardIndex];show(`<section class="panel study-panel"><div class="study-top"><span>Card ${cardIndex+1} of ${cards.length}</span><label><input type="checkbox" id="filter" ${filterCards?'checked':''}> Practice only</label><button class="text-btn" id="home">MAIN MENU</button></div><button class="flashcard ${cardFlipped?'definition':''}" id="flip" aria-label="Flip flashcard">${cardFlipped?v.definition:v.term}<small>TAP TO ${cardFlipped?'SEE WORD':'FLIP'}</small></button><div class="row"><button class="secondary" id="previous">← PREVIOUS</button><button class="secondary" id="shuffle">SHUFFLE</button><button class="secondary" id="next">NEXT →</button></div><div class="row"><button class="primary" id="know">✓ I KNOW THIS</button><button class="secondary" id="need">✦ NEED PRACTICE</button></div><p class="feedback" id="card-note">${progress.stats[v.id].needsPractice?'Marked for practice.':'Keep exploring your 13 science words.'}</p></section>`);on('flip',()=>{cardFlipped=!cardFlipped;renderCard();});on('previous',()=>moveCard(-1));on('next',()=>moveCard(1));on('shuffle',()=>{cards=shuffle(cards);cardIndex=0;cardFlipped=false;renderCard();});on('filter',()=>openStudy($('filter').checked));on('home',mainMenu);on('need',()=>{progress.stats[v.id].needsPractice=true;progress.stats[v.id].latest='Self-rated: practice';save();$('card-note').textContent='Added to your practice collection.';});on('know',()=>{progress.stats[v.id].latest='Self-rated: known';save();$('card-note').textContent=progress.stats[v.id].needsPractice?'Feeling confident! Use Practice My Mistakes to clear this word with a first-try answer.':'Feeling confident! Adventure answers measure your mastery.';});}
function moveCard(n){cardIndex=(cardIndex+n+cards.length)%cards.length;cardFlipped=false;renderCard();}
controls=bindControls({getState:()=>input,isPlaying:()=>mode==='play',interact,escape:()=>{if(mode==='play')pause();else if(mode==='pause')$('resume').click();}});
window.addEventListener('blur',()=>{resetInput();pause();});document.addEventListener('visibilitychange',()=>{resetInput();if(document.hidden){pause();save();}});window.addEventListener('pagehide',()=>{if(world&&progress.run)saveRun();else save();});window.addEventListener('resize',()=>{if(innerHeight>innerWidth){resetInput();pause();}resizeCanvas();});
document.addEventListener('contextmenu',e=>e.preventDefault());
function resizeCanvas(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect(),scale=Math.min(2,r.width/1200*dpr);canvas.width=Math.round(1200*scale);canvas.height=Math.round(720*scale);ctx.setTransform(canvas.width/1200,0,0,canvas.height/720,0,0);}
function tick(dt){
 if(mode!=='play')return;if(innerHeight>innerWidth){pause();return;}const jumped=input.jump;input.jump=false;const frameInput={left:input.left,right:input.right,jump:jumped};const fell=updatePhysics(player,world,frameInput,dt);if(frameInput.didJump)sound('jump');if(fell)damage();
 for(const x of [2250,3950,5650])if(player.x>=x&&checkpoint<x){checkpoint=x;player.checkpoint=x;saveRun();toast('Checkpoint saved! ⚑');sound('open');}
 for(const c of world.crystals){if(!c.taken&&Math.abs(player.x+16-c.x)<30&&Math.abs(player.y+25-c.y)<47){c.taken=true;progress.run.crystals+=c.bonus?5:1;progress.run.score+=c.bonus?50:10;burst(c.x,c.y,c.bonus?'#ffe49c':'#bca7ff',8);sound('crystal');saveRun();}}
 rockClock+=dt;if(world.index>0&&rockClock>4.5&&player.x>500&&player.x<5700&&!nearestStation()){rockClock=0;world.rocks.push({x:player.x+180,y:-30,vy:70});}
 for(const r of world.rocks){r.vy+=150*dt;r.y+=r.vy*dt;if(Math.abs(player.x+16-r.x)<29&&r.y>player.y&&r.y<player.y+58)damage();}world.rocks=world.rocks.filter(r=>r.y<650);
 const station=nearestStation();$('action').hidden=!station;if(station)$('action').textContent=station.type==='boss'?`◆ SCIENCE CRYSTAL ${progress.run.bossDone+1}/3`:'✦ EXPLORE';
 if(player.x>5850&&world.stations.every(s=>s.done))levelEnd();
 camera+=(Math.max(0,Math.min(world.width-1200,player.x-390))-camera)*Math.min(1,dt*7);if(clock>=nextHudAt){updateHud();nextHudAt=clock+.1;}
}
let last=performance.now(),accumulator=0;
function frame(now){if(disposed)return;const dt=Math.min(.05,(now-last)/1000);last=now;clock+=dt;accumulator+=dt;while(accumulator>=1/120){tick(1/120);accumulator-=1/120;}effects.forEach(e=>{e.life-=dt;e.x+=e.vx*dt;e.y+=e.vy*dt;e.vy+=500*dt;});effects=effects.filter(e=>e.life>0);bossPulse=Math.max(0,bossPulse-dt);
 if(world&&['play','pause','question','level','result'].includes(mode)){world.bossCharge=progress.run?.bossDone??3;drawWorld(ctx,world,player,camera,clock,effects);if(bossPulse>0){ctx.fillStyle=`rgba(175,255,220,${bossPulse*.12})`;ctx.fillRect(0,0,1200,720);}if(mode==='result'){for(let i=0;i<25;i++){crystal(ctx,(i*137)%1200,(clock*60+i*73)%800-50,.35,['#ffd78b','#b4a2fa','#a3f0d8'][i%3],clock);}}}else titleArt(ctx,clock);
 if(clock>toastUntil)$('toast').classList.remove('visible');frameId=requestAnimationFrame(frame);
}
resizeCanvas();mainMenu();frameId=requestAnimationFrame(frame);
registerAdventure({player:'ari',save:()=>{if(progress.run&&world)saveRun();else save();},stop:async()=>{disposed=true;cancelAnimationFrame(frameId);controls.destroy();await audioEngine.close();try{speechSynthesis.cancel();}catch{}}});
// Read-only diagnostics make automated checks observe the real game, without gameplay shortcuts.
Object.defineProperty(window,'volcanoQuest',{get:()=>({mode,player:player?{...player}:null,world:world?{index:world.index,stations:world.stations.map(s=>({...s})),crystals:world.crystals.map(c=>({...c})),platforms:world.platforms.map(s=>({...s})),rocks:world.rocks.map(r=>({...r}))}:null,checkpoint,question:question?{id:question.id,attempt:question.attempt,solved:question.solved}:null,progress:JSON.parse(JSON.stringify(progress)),input:{...input}})});
